<?php
if(!defined('ABSPATH'))exit;
add_action('admin_menu',function(){add_menu_page('Fraztech','Fraztech','manage_options','fraztech','ft_dashboard','dashicons-art',3);add_submenu_page('fraztech','Setup & import','Setup & import','manage_options','fraztech','ft_dashboard');add_submenu_page('fraztech','Profile settings','Profile settings','manage_options','ft-settings','ft_settings_page');add_submenu_page('fraztech','Complaints','Complaints','manage_options','ft-complaints','ft_inbox_page');});
function ft_dashboard(){if(!current_user_can('manage_options'))return;echo '<div class="wrap"><h1>Fraztech</h1><p>Your design and content, managed in WordPress.</p><h2>Set up the approved website</h2><p>Activate the Fraztech theme first. The importer adds the supplied pages, articles, projects, services, packages, FAQs, videos and media. Existing imported entries are skipped, so running it again does not overwrite your edits.</p><p>Run this on your Fraztech installation only. Take a backup before importing. Importing sets the homepage and article permalink structure.</p>';
 if(get_stylesheet()!=='fraztech')echo '<p><strong>Activate the Fraztech theme in Appearance → Themes before importing.</strong></p>';
 else echo '<button class="button button-primary" id="ft-import">Import approved content</button><p id="ft-import-status" role="status"></p>';
 echo '<h2>Edit your website</h2><ul><li><a href="'.esc_url(admin_url('edit.php?post_type=page')).'">Pages</a>: edit existing page copy, images and links in “Design content”.</li><li><a href="'.esc_url(admin_url('edit.php')).'">Posts</a>: articles. New articles use the editor, a featured image and card details.</li><li>Services / Projects: manage detail pages and listing cards. Set a project collection to Mobile apps, Websites or Work.</li><li>Packages / FAQs: edit the shared cards shown across the website.</li><li>Client Stories: publish videos or written reviews; real client media requires permission.</li><li>AI Tools: add or update tools, official links, logos and category groups.</li><li>Profile settings: update social links and GitHub.</li><li>Complaints: private submissions and evidence. No email notification is configured; check the inbox regularly.</li></ul><p>Imported designs use protected layouts. For a new layout you can create a normal page with the editor. No page-builder subscription is required.</p></div>';
}
add_action('admin_enqueue_scripts',function($hook){if(str_contains($hook,'fraztech')||str_contains($hook,'ft-')||in_array($hook,['post.php','post-new.php'],true)){wp_enqueue_media();wp_enqueue_script('ft-admin',plugins_url('admin.js',__FILE__),['jquery'],'1.0.0',true);wp_localize_script('ft-admin','ftAdmin',['ajax'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('ft_import')]);wp_enqueue_style('ft-admin',plugins_url('admin.css',__FILE__),[],'1.0.0');}});
add_action('admin_init',function(){register_setting('ft_settings','ft_settings',['sanitize_callback'=>function($values){$out=[];foreach(['fiverr','linkedin','upwork','dribbble','behance','facebook','instagram','whatsapp','github'] as $key)$out[$key]=esc_url_raw($values[$key]??'',['https','http']);$out['email']=sanitize_email($values['email']??'info@fraztech.com');return $out;}]);});
function ft_settings_page(){if(!current_user_can('manage_options'))return;$defaults=['fiverr'=>'https://www.fiverr.com/s/wbkdkmq','linkedin'=>'https://www.linkedin.com/in/faraz-khan-4b8235256','upwork'=>'https://www.upwork.com/freelancers/~0159ec3f835c4a7b67?mp_source=share','dribbble'=>'https://dribbble.com/FarazDesign','behance'=>'https://www.behance.net/farazdesign10','facebook'=>'https://www.facebook.com/profile.php?id=61575625778962','instagram'=>'https://www.instagram.com/f_ara_zi?stkn=MWhnNDJ3ODlmemx0YQ==','whatsapp'=>'https://wa.me/923487096356','github'=>'','email'=>'info@fraztech.com'];echo '<div class="wrap"><h1>Fraztech profile settings</h1><form action="options.php" method="post">';settings_fields('ft_settings');echo '<table class="form-table">';foreach($defaults as $key=>$default)echo '<tr><th><label for="ft-'.$key.'">'.esc_html(ucfirst($key)).'</label></th><td><input class="large-text" type="'.($key==='email'?'email':'url').'" id="ft-'.$key.'" name="ft_settings['.$key.']" value="'.esc_attr(ft_setting($key,$default)).'">'.($key==='whatsapp'?'<p>Use https://wa.me/ followed by your country code and number, without + or spaces.</p>':'').'</td></tr>';echo '</table>';submit_button();echo '</form></div>';}
add_filter('use_block_editor_for_post',function($use,$post){return get_post_meta($post->ID,'_ft_layout',true)?false:$use;},10,2);
add_action('add_meta_boxes',function(){foreach(array_merge(['page','post'],array_keys(ft_types())) as $type){add_meta_box('ft-content','Design content: text, images and links','ft_content_box',$type,'normal','high');if($type!=='page')add_meta_box('ft-card','Listing card & publishing details','ft_card_box',$type,'normal','high');}});
function ft_edit_nodes($dom){$xp=new DOMXPath($dom);$out=[];foreach($xp->query('//*[@id="ft-root"]//text()[normalize-space()]') as $n){$parent=$n->parentNode;$skip=false;for($p=$parent;$p && $p instanceof DOMElement;$p=$p->parentNode){if(in_array(strtolower($p->tagName),['script','style','svg'],true)){$skip=true;break;}}if(!$skip&&!str_contains($n->nodeValue,'[ft_'))$out[]=['node'=>$n,'attr'=>'','value'=>$n->nodeValue,'label'=>$parent->nodeName];}
 foreach($xp->query('//*[@id="ft-root"]//*[@src or @href or @poster]') as $n){if($n->tagName==='svg'||$n->tagName==='path')continue;foreach(['src','href','poster'] as $attr){if($n->hasAttribute($attr))$out[]=['node'=>$n,'attr'=>$attr,'value'=>$n->getAttribute($attr),'label'=>$n->tagName.' '.$attr];}}
 return $out;}
function ft_content_box($post){if(!current_user_can('manage_options')){echo '<p>Layout editing is available to administrators.</p>';return;}wp_nonce_field('ft_edit_'.$post->ID,'ft_edit_nonce');$has=false;foreach(['layout'=>'Page content','card'=>'Shared card content'] as $key=>$label){$html=get_post_meta($post->ID,'_ft_'.$key,true);if(!$html)continue;$has=true;$dom=ft_dom($html);echo '<details class="ft-edit-group"><summary>'.esc_html($label).'</summary><p>Edit the fields below to keep the approved layout. Fields containing /assets/ point to the bundled images. Use Choose media to replace them.</p>';foreach(ft_edit_nodes($dom) as $i=>$f){$id='ft-'.$key.'-'.$i;$name='ft_nodes['.$key.']['.$i.']';echo '<label class="ft-edit-label" for="'.$id.'">'.esc_html(($i+1).' · '.$f['label']).'</label>';if($f['attr']){echo '<div class="ft-media-row"><input type="text" class="large-text" id="'.$id.'" name="'.$name.'" value="'.esc_attr($f['value']).'">';if(in_array($f['attr'],['src','poster'],true))echo '<button type="button" class="button ft-media" data-target="'.$id.'">Choose media</button>';echo '</div>';}else echo '<textarea class="large-text" rows="2" id="'.$id.'" name="'.$name.'">'.esc_textarea($f['value']).'</textarea>';}
 echo '</details>';}
 if(!$has)echo '<p>This is a new entry. Write its content in the WordPress editor and fill in its listing details below.</p>';else echo '<p>Use these fields for imported content. The regular editor is used only for new entries without a protected layout.</p>';
}
function ft_card_box($post){wp_nonce_field('ft_edit_'.$post->ID,'ft_card_nonce');echo '<p>These fields control the card shown on listing pages. Page text is edited separately above.</p>';foreach(['card_title'=>'Card title (blank uses entry title)','excerpt'=>'Short description','category'=>'Category / topic','image'=>'Card image URL (or use Featured image)','video'=>'MP4 video URL (Client Stories)','price'=>'Price label','url'=>'Official website URL (AI Tools)'] as $key=>$label){$id='ft-meta-'.$key;echo '<p><label for="'.$id.'"><strong>'.esc_html($label).'</strong></label><div class="ft-media-row"><input class="large-text" id="'.$id.'" name="ft_meta['.$key.']" value="'.esc_attr(get_post_meta($post->ID,'_ft_'.$key,true)).'">';if(in_array($key,['image','video'],true))echo '<button type="button" class="button ft-media" data-target="'.$id.'">Choose media</button>';echo '</div></p>';}
 if($post->post_type==='ft_tool'){echo '<p><label>Tool category <select name="ft_meta[group]">';foreach(ft_tool_categories() as $v=>$l)echo '<option value="'.esc_attr($v).'" '.selected(get_post_meta($post->ID,'_ft_group',true),$v,false).'>'.esc_html($l).'</option>';echo '</select></label></p>';}
 if($post->post_type==='ft_project'){echo '<p><label>Collection <select name="ft_meta[group]">';foreach(['mobile-apps'=>'Mobile apps','websites'=>'Websites','work'=>'Selected work'] as $v=>$l)echo '<option value="'.$v.'" '.selected(get_post_meta($post->ID,'_ft_group',true),$v,false).'>'.$l.'</option>';echo '</select></label></p>';}
 if($post->post_type==='ft_story'){foreach(['demo'=>'This is a clearly labeled demo, not a real client endorsement.','permission'=>'I have prior client permission to publish this media / review.'] as $key=>$label)echo '<p><label><input type="checkbox" name="ft_meta['.$key.']" value="1" '.checked(get_post_meta($post->ID,'_ft_'.$key,true),'1',false).'>'.esc_html($label).'</label></p>';echo '<p>Real client stories are hidden from the website until permission is checked. To replace an imported demo, create a new Client Story and move the demo to Trash.</p>';}
}
add_action('save_post',function($id,$post){if(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE||wp_is_post_revision($id)||!current_user_can('edit_post',$id))return;$nonce=$_POST['ft_edit_nonce']??$_POST['ft_card_nonce']??'';if(!wp_verify_nonce($nonce,'ft_edit_'.$id))return;
 if(isset($_POST['ft_nodes_json'])&&is_string($_POST['ft_nodes_json'])){$_POST['ft_nodes']=wp_slash(json_decode(wp_unslash($_POST['ft_nodes_json']),true)?:[]);}
 if(current_user_can('manage_options')&&isset($_POST['ft_nodes']))foreach(['layout','card'] as $key){$html=get_post_meta($id,'_ft_'.$key,true);if(!$html)continue;$dom=ft_dom($html);$data=wp_unslash($_POST['ft_nodes'][$key]??[]);foreach(ft_edit_nodes($dom) as $i=>$f){if(!isset($data[$i])||!is_string($data[$i]))continue;$val=$data[$i];if($f['attr']){$val=esc_url_raw($val,['http','https','mailto','tel']);$f['node']->setAttribute($f['attr'],$val);}else $f['node']->nodeValue=sanitize_textarea_field($val);}
 update_post_meta($id,'_ft_'.$key,wp_slash(ft_dom_html($dom)));}
 if(isset($_POST['ft_meta'])&&is_array($_POST['ft_meta'])){$values=wp_unslash($_POST['ft_meta']);foreach(['card_title','excerpt','category','image','video','price','group','url'] as $key)if(isset($values[$key])&&is_string($values[$key]))update_post_meta($id,'_ft_'.$key,in_array($key,['image','video','url'],true)?esc_url_raw($values[$key]):sanitize_text_field($values[$key]));if($post->post_type==='ft_story')foreach(['demo','permission'] as $key)update_post_meta($id,'_ft_'.$key,empty($values[$key])?0:1);}
},10,2);

function ft_tool_categories(){return ['chat-assistants'=>'Chat & assistants','image-generation'=>'Image generation','video-creation-editing'=>'Video creation & editing','writing-content'=>'Writing & content','coding-app-building'=>'Coding & app building','ui-design-websites'=>'UI, design & websites','productivity-meetings'=>'Productivity & meetings','voice-audio-music'=>'Voice, audio & music','research-learning'=>'Research & learning','automation-chatbots'=>'Automation & chatbots'];}
